/*
 * DS3231 RTC Clock with LCD Display
 *
 * Wiring:
 *   DS3231 VCC -> 5V
 *   DS3231 GND -> GND
 *   DS3231 SCL -> SCL
 *   DS3231 SDA -> SDA
 *   LCD VCC    -> 5V
 *   LCD GND    -> GND
 *   LCD SCL    -> SCL
 *   LCD SDA    -> SDA
 *   LED anode  -> D13 / GPIO 2 (via 220 ohm resistor)
 */

#include <Wire.h>
#include <RtcDS3231.h>
#include <LiquidCrystal_I2C.h>

RtcDS3231<TwoWire> Rtc(Wire);
LiquidCrystal_I2C lcd(0x27, 16, 2);

const int LED_PIN = 2;
bool ledState = false;

void setup() {
  Serial.begin(115200);
  pinMode(LED_PIN, OUTPUT);

  Wire.begin();
  lcd.init();
  lcd.backlight();
  lcd.setCursor(0, 0);
  lcd.print("Initializing...");

  Rtc.Begin();

  if (!Rtc.IsDateTimeValid()) {
    Serial.println("RTC lost power - setting compile time");
    Rtc.SetDateTime(RtcDateTime(__DATE__, __TIME__));
  }

  if (!Rtc.IsRunning()) {
    Serial.println("RTC not running, starting now");
    Rtc.SetIsRunning(true);
  }

  lcd.clear();
  Serial.println("DS3231 RTC Clock Started");
  Serial.println("-----------------------------");
}

void loop() {
  RtcDateTime now = Rtc.GetDateTime();
  RtcTemperature temp = Rtc.GetTemperature();

  if (now.Hour() < 10) Serial.print("0");
  Serial.print(now.Hour());
  Serial.print(":");
  if (now.Minute() < 10) Serial.print("0");
  Serial.print(now.Minute());
  Serial.print(":");
  if (now.Second() < 10) Serial.print("0");
  Serial.print(now.Second());
  Serial.print("  ");
  if (now.Day() < 10) Serial.print("0");
  Serial.print(now.Day());
  Serial.print("/");
  if (now.Month() < 10) Serial.print("0");
  Serial.print(now.Month());
  Serial.print("/");
  Serial.print(now.Year());
  Serial.print("  Temp: ");
  Serial.print(temp.AsFloatDegC(), 1);
  Serial.println(" C");

  lcd.setCursor(0, 0);
  if (now.Hour() < 10) lcd.print("0");
  lcd.print(now.Hour());
  lcd.print(":");
  if (now.Minute() < 10) lcd.print("0");
  lcd.print(now.Minute());
  lcd.print(":");
  if (now.Second() < 10) lcd.print("0");
  lcd.print(now.Second());
  lcd.print("  ");
  lcd.print(temp.AsFloatDegC(), 1);
  lcd.print("C");

  lcd.setCursor(0, 1);
  if (now.Day() < 10) lcd.print("0");
  lcd.print(now.Day());
  lcd.print("/");
  if (now.Month() < 10) lcd.print("0");
  lcd.print(now.Month());
  lcd.print("/");
  lcd.print(now.Year());

  ledState = !ledState;
  digitalWrite(LED_PIN, ledState ? HIGH : LOW);

  delay(1000);
}
